    return p[:-5].replace('/','.')
# all .lean under AlgebraicJacobian/ plus the root file
files=[]
for dp,dn,fn in os.walk(root):
    for f in fn:
        if f.endswith('.lean'): files.append(os.path.join(dp,f))
files_sub=sorted(files)
rootfile=root+'.lean'
allfiles=files_sub+([rootfile] if os.path.exists(rootfile) else [])
imp_re=re.compile(r'^import\s+([A-Za-z0-9_.]+)',re.M)
graph={}
for p in allfiles:
    m=modname(p)
    txt=open(p,encoding='utf-8',errors='replace').read()
    graph[m]=[i for i in imp_re.findall(txt) if i.split('.')[0]==root]
print("files under AlgebraicJacobian/ :",len(files_sub))
print("total incl root module        :",len(allfiles))
# BFS from root module
seen=set()
dq=collections.deque([root])
while dq:
    x=dq.popleft()
    if x in seen: continue
    seen.add(x)
    for y in graph.get(x,[]):
        if y not in seen: dq.append(y)
present=set(graph)
reach=seen & present
unreach=sorted(present-seen)
print("reachable (present modules)   :",len(reach))
print("UNROOTED count                :",len(unreach))
for u in unreach: print("   ",u)
dangling=sorted({i for v in graph.values() for i in v} - present)
print("dangling import targets (named but no file):",len(dangling))
for d in dangling[:20]: print("   MISSING:",d)
